"""Keep generated bytes independent of the Python 3.12 float-sum change."""
from __future__ import annotations

import json
import math
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

from psf import charts, model, runtime
from psf.script import emit


ROOT = Path(__file__).resolve().parents[1]


def python311_sum(values):
    """The sequential float accumulation used before Python 3.12."""
    total = 0
    for value in values:
        total += value
    return total


class CrossVersionGenerationTests(unittest.TestCase):
    def test_fractional_bookmarks_have_identical_reports_and_artwork(self):
        manifest = model.load(ROOT / "examples/vanilla/manifest.json")
        profiles = {profile["id"]: profile for profile in manifest["profiles"]}
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            for profile, date in (("ita", "1936.1.1"), ("ita", "1939.8.14"), ("chi", "1936.1.1")):
                outputs = []
                for index, algorithm in enumerate((python311_sum, math.fsum)):
                    target = root / str(index)
                    # Simulate the two interpreter versions without requiring
                    # their installations or changing any authored game data.
                    with patch.object(charts, "sum", algorithm, create=True):
                        report = charts.bookmark_artwork(manifest, profiles[profile], date, target)
                    outputs.append((json.dumps(report, sort_keys=True).encode(),
                                    (target / report["texture"]).read_bytes()))
                with self.subTest(profile=profile, date=date):
                    self.assertEqual(outputs[0][0], outputs[1][0], "Bookmark report bytes differ")
                    self.assertEqual(outputs[0][1], outputs[1][1], "Bookmark texture bytes differ")

    def test_fractional_axis_weights_emit_identical_distance_divisors(self):
        # Both sums are close, but they straddle the emitter's six-place
        # rounding boundary and used to change the actual scripted divisor.
        weights = [.017292, .0493, .184517, .166646, .5822455]
        self.assertNotEqual(python311_sum(weights), math.fsum(weights))
        pairs = [("psf_axis_" + str(index), 0, weight) for index, weight in enumerate(weights)]
        scripts = []
        for algorithm in (python311_sum, math.fsum):
            with patch.object(runtime, "sum", algorithm, create=True):
                scripts.append(emit(runtime.distance("psf_distance", pairs)))
        self.assertEqual(scripts[0], scripts[1])


if __name__ == "__main__":
    unittest.main()
